TEST(compile_test, format_nullptr) {
  auto expected = fmt::format(fmt::runtime("{}"), nullptr);
  EXPECT_EQ("0x0", expected);
  EXPECT_EQ(expected, fmt::format(FMT_COMPILE("{}"), nullptr));
  std::nullptr_t value = nullptr;
  EXPECT_EQ(expected, fmt::format(FMT_COMPILE("{}"), value));
  auto surrounded = fmt::format(fmt::runtime("before {} after"), nullptr);
  EXPECT_EQ(surrounded,
            fmt::format(FMT_COMPILE("before {} after"), nullptr));
  EXPECT_EQ(surrounded,
            fmt::format(FMT_COMPILE("before {} after"), value));
  EXPECT_EQ(fmt::format(fmt::runtime("[{:p}]"), nullptr),
            fmt::format(FMT_COMPILE("[{:p}]"), nullptr));
  EXPECT_EQ(fmt::format(fmt::runtime("[{:>8p}]"), nullptr),
            fmt::format(FMT_COMPILE("[{:>8p}]"), value));
}

TEST(compile_test, nullptr_output) {
  auto expected = fmt::format(fmt::runtime("[{}]"), nullptr);
  std::vector<char> output;
  fmt::format_to(std::back_inserter(output), FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(expected, std::string(output.begin(), output.end()));

  char full[6] = {};
  full[5] = '!';
  auto result = fmt::format_to_n(full, 5, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(expected.size(), result.size);
  EXPECT_EQ(full + 5, result.out);
  EXPECT_EQ("[0x0]!", fmt::string_view(full, 6));

  char truncated[4] = {'!', '!', '!', '!'};
  result = fmt::format_to_n(truncated, 3, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(expected.size(), result.size);
  EXPECT_EQ(truncated + 3, result.out);
  EXPECT_EQ("[0x!", fmt::string_view(truncated, 4));

  result = fmt::format_to_n(truncated, 0, FMT_COMPILE("[{}]"), nullptr);
  EXPECT_EQ(expected.size(), result.size);
  EXPECT_EQ(truncated, result.out);
  EXPECT_EQ("[0x!", fmt::string_view(truncated, 4));
  EXPECT_EQ(3u, fmt::formatted_size(FMT_COMPILE("{}"), nullptr));
  EXPECT_EQ(expected.size(),
            fmt::formatted_size(FMT_COMPILE("[{}]"), nullptr));
}

TEST(compile_test, string_and_pointer_compatibility) {
  char mutable_string[] = "text";
  const char* const_string = "text";
  auto string = std::string("text");
  EXPECT_EQ("text", fmt::format(FMT_COMPILE("{}"), "text"));
  EXPECT_EQ("[text]", fmt::format(FMT_COMPILE("[{}]"), "text"));
  EXPECT_EQ("text", fmt::format(FMT_COMPILE("{}"), mutable_string));
  EXPECT_EQ("[text]", fmt::format(FMT_COMPILE("[{}]"), mutable_string));
  EXPECT_EQ("text", fmt::format(FMT_COMPILE("{}"), const_string));
  EXPECT_EQ("[text]", fmt::format(FMT_COMPILE("[{}]"), const_string));
  EXPECT_EQ("text", fmt::format(FMT_COMPILE("{}"), string));
  EXPECT_EQ("[text]", fmt::format(FMT_COMPILE("[{}]"), string));
  EXPECT_THROW((void)fmt::format(FMT_COMPILE("[{:s}]"),
                                static_cast<const char*>(nullptr)),
               fmt::format_error);

  void* null_pointer = nullptr;
  const void* pointer = &mutable_string;
  EXPECT_EQ(fmt::format(fmt::runtime("{}"), null_pointer),
            fmt::format(FMT_COMPILE("{}"), null_pointer));
  EXPECT_EQ(fmt::format(fmt::runtime("[{}]"), null_pointer),
            fmt::format(FMT_COMPILE("[{}]"), null_pointer));
  EXPECT_EQ(fmt::format(fmt::runtime("{}"), pointer),
            fmt::format(FMT_COMPILE("{}"), pointer));
  EXPECT_EQ(fmt::format(fmt::runtime("[{}]"), pointer),
            fmt::format(FMT_COMPILE("[{}]"), pointer));
}

